using Content.Shared._VG.Armor;
using Content.Shared._VG.Body;
using Robust.Shared.Prototypes;
using Robust.Shared.Serialization;

namespace Content.Shared._VG.Clothing;

/// <summary>
///     vg13 properties of a worn item (armor, coverage, slowdown), keyed by its entity prototype id; children
///     inherit through their parents. Kept apart from the entity prototypes so upstream SS14 clothing isn't edited.
///     Generated by Tools/_VG/clothing.
/// </summary>
[Prototype("vgClothing")]
public sealed partial class VgClothingPrototype : IPrototype
{
    [IdDataField]
    public string ID { get; private set; } = default!;

    /// <summary>
    ///     vg13 armor: percent of the damage blocked, per category (melee, bullet, laser, energy, bomb, bio, rad).
    /// </summary>
    [DataField]
    public Dictionary<string, float> Armor = new();

    /// <summary>
    ///     vg13 armor_absorb: damage under this much is scaled down further (damage * damage / absorb).
    /// </summary>
    [DataField]
    public Dictionary<string, float> Absorb = new();

    /// <summary>
    ///     vg13 body_parts_covered: limbs this item protects.
    /// </summary>
    [DataField]
    public List<VgBodyParts> Coverage = new();

    /// <summary>
    ///     vg13 slowdown: multiplies the wearer's move delay (2 = half speed). Back items count for half.
    /// </summary>
    [DataField]
    public float Slowdown = 1;

    /// <summary>
    ///     vg13 heat_conductivity: how much heat the covered skin still loses through it (0 insulates fully). Null means
    ///     the slot's default.
    /// </summary>
    [DataField]
    public float? HeatConductivity;

    /// <summary>
    ///     vg13 max_heat_protection_temperature: the covered parts are kept from heating up in air up to this hot, K.
    /// </summary>
    [DataField]
    public float? MaxHeatProtection;

    public VgBodyParts CoverageFlags
    {
        get
        {
            var flags = VgBodyParts.None;
            foreach (var part in Coverage)
            {
                flags |= part;
            }

            return flags;
        }
    }

    public float Get(VgArmorType type)
    {
        return Armor.GetValueOrDefault(Key(type));
    }

    public float GetAbsorb(VgArmorType type)
    {
        return Absorb.GetValueOrDefault(Key(type));
    }

    public static string Key(VgArmorType type)
    {
        return type.ToString().ToLowerInvariant();
    }
}
